-- Test Case Step (Step Definition Name Initial)
SELECT  '- Enter Text to Filter Step Definition -' as label,'- Enter Text to Filter Step Definition -' as NAME,null as ID,'- Enter Text to Filter Step Definition -' as value FROM STEP_DEFINITION_TEMPLATE_VERBIAGE UNION SELECT STEP_DEFINITION_TEMPLATE_VERBIAGE_NAME as label,STEP_DEFINITION_TEMPLATE_VERBIAGE_NAME as NAME,STEP_DEFINITION_TEMPLATE_VERBIAGE_UUID as ID,STEP_DEFINITION_TEMPLATE_VERBIAGE_UUID as value FROM STEP_DEFINITION_TEMPLATE_VERBIAGE
where IS_POSSIBLE_FIRST_STEP='Yes' AND IS_ACTIVE_STEP_DEFINITION_TEMPLATE_VERBIAGE = 'Yes' AND (CONCAT(',',:STEP_FILTER,',') like CONCAT('%,',STEP_FILTER,',%') OR STEP_FILTER LIKE :STEP_DEFINITION_FILTER) UNION
SELECT STEP_DEFINITION_TEMPLATE_VERBIAGE_NAME as label,STEP_DEFINITION_TEMPLATE_VERBIAGE_NAME as NAME,STEP_DEFINITION_TEMPLATE_VERBIAGE_UUID as ID,STEP_DEFINITION_TEMPLATE_VERBIAGE_UUID as value FROM STEP_DEFINITION_TEMPLATE_VERBIAGE where STEP_DEFINITION_TEMPLATE_VERBIAGE_UUID=:STEP_DEFINITION_TEMPLATE_VERBIAGE_UUID


